// Runs when the user clicks "Analyse my finances". Mode: Run Once for All Items.

// --- Config ---
const ALLOWED_SOURCES = new Set(['receipt', 'document', 'voice', 'manual'])
const ALLOWED_CATEGORIES = new Set([
  'groceries', 'dining', 'transport', 'fuel', 'utilities', 'rent', 'telecom',
  'health', 'education', 'clothing', 'household', 'entertainment',
  'subscriptions', 'gifts', 'festival', 'salary', 'other',
])

// Python-style rounding (half to even), so amounts match the earlier Python version exactly.
function pyRound(value) {
  const floor = Math.floor(value)
  const diff = value - floor
  if (diff > 0.5) return floor + 1
  if (diff < 0.5) return floor
  return floor % 2 === 0 ? floor : floor + 1
}

// Mauritius time: UTC+4, no daylight saving.
function mauritiusNow(offsetDays = 0) {
  const shifted = new Date(Date.now() + 4 * 3600e3 + offsetDays * 86400e3).toISOString()
  return { date: shifted.slice(0, 10), stamp: shifted.slice(0, 19) + '+04:00' }
}

function validDateOrToday(rawDate) {
  if (typeof rawDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(rawDate)) {
    const [year, month, day] = rawDate.split('-').map(Number)
    const check = new Date(Date.UTC(year, month - 1, day))
    if (check.getUTCFullYear() === year && check.getUTCMonth() === month - 1 && check.getUTCDate() === day) return rawDate
  }
  return mauritiusNow().date
}

// --- Input: Auth Bouncer output (body fields + verified userId) ---
const request = $input.first().json
const rawLines = request.lineItems || []
if (!Array.isArray(rawLines) || !rawLines.length) throw new Error('INVALID_CONFIRMATION: no line items sent')

const lineItems = rawLines.map((rawLine) => {
  const price = pyRound(Number(rawLine.price ?? 0))
  const quantity = Number(rawLine.qty || 1)
  if (!Number.isFinite(price) || !Number.isFinite(quantity)) throw new Error('INVALID_CONFIRMATION: price and quantity must be numbers')
  if (price < 0 || quantity <= 0) throw new Error('INVALID_CONFIRMATION: negative price or zero quantity')
  const category = String(rawLine.category || 'other').trim().toLowerCase()
  return {
    name: rawLine.name || 'item',
    price,
    qty: quantity,
    category: ALLOWED_CATEGORIES.has(category) ? category : 'other',
    direction: rawLine.direction === 'income' ? 'income' : 'expense',
  }
})

const lineTotal = (line) => pyRound(line.price * line.qty)
const source = ALLOWED_SOURCES.has(request.source) ? request.source : 'manual'

// --- Output: same shape as the Guardrail, already approved by the user ---
return [{ json: {
  userId: request.userId,
  vendor: request.vendor ?? null,
  totalCents: lineItems.reduce((sum, line) => sum + lineTotal(line), 0),
  lineItems,
  flags: [],
  requiresValidation: false,
  txnDate: validDateOrToday(request.txnDate),
  dateSource: 'user',
  confidenceScore: 1.0,
  source,
  docType: String(request.docType || '').trim().toLowerCase(),
  incomeCents: lineItems.filter((line) => line.direction === 'income').reduce((sum, line) => sum + lineTotal(line), 0),
} }]

// --- Auth Bouncer (Code node) ---
// Runs after "Verify Firebase Token", which asked Google to check the ID token.
// Any userId or email sent by the client is dropped and replaced.
// Mode: Run Once for All Items.
const IDENTITY_FIELDS = ['userId', 'email']

const users = $input.first().json.users || []
if (!users.length) throw new Error('UNAUTHORIZED: no Firebase user for this token')
const verifiedUser = users[0]

// --- Output: the request body plus the verified identity ---
const requestBody = $('Webhook').first().json.body || {}
const safeBody = Object.fromEntries(
