// --- Input: Affordability Algorithm output ---
const result = $input.first().json

// --- Map the verdict onto the goals.status values ---
function goalStatus(verdict, reachable) {
  if (verdict === 'TIGHT') return 'tight'
  if (verdict === 'NOT_SAFE' && !reachable) return 'stalled'
  return 'on-track'
}

const itemLabel = result.itemName || 'cash-' + String(result.targetAmountCents)
// An edit (updateGoal) keeps the key of the goal being edited.
const goalKey = result.goalKey || result.userId + ':' + String(itemLabel).trim().toLowerCase()

// --- Output: goals schema plus goalKey (the upsert match key) ---
return [{ json: {
  goalKey,
  userId: result.userId,
  goalType: result.goalType || 'product',
  itemName: result.itemName || '',
  targetAmount: result.targetAmountCents ?? 0,
  link: result.link ?? null,
  savedAmount: Math.trunc(Number(result.savedAmountCents || 0)),
  verdict: result.verdict ?? null,
  timelineMonths: result.monthsNeeded ?? 0,
  status: goalStatus(result.verdict, result.reachable ?? true),
  updatedAt: mauritiusNow().stamp,
} }]

// --- Build Acknowledgement (Code node, right before Respond Result) ---
// Every saving branch ends here. Detects what arrived and returns a short receipt.
// Mode: Run Once for All Items.

const incoming = $input.all().map((entry) => entry.json)
const first = incoming[0] || {}
const ack = (record, saved, messageKey, extra = {}) => [{ json: { success: true, saved, record, messageKey, ...extra } }]

// --- Transactions inserted (one item per saved transaction) ---
if ('amount' in first && 'direction' in first) {
  return ack('transaction', true, 'TRANSACTION_SAVED', {
    count: incoming.length,
    totalCents: incoming.reduce((sum, doc) => sum + Math.trunc(Number(doc.amount ?? 0)), 0),
    ids: incoming.map((doc) => doc.id || doc._id || null),
  })
}

// --- Goal upserted (a goal document has targetAmount; the afford result does not) ---
if ('goalKey' in first && 'targetAmount' in first) {
  return ack('goal', true, 'GOAL_SAVED', {
    goalKey: first.goalKey ?? null,
    savedAmountCents: first.savedAmount ?? null,
    verdict: first.verdict ?? null,
    itemName: first.itemName ?? null,
    timelineMonths: first.timelineMonths ?? null,
    status: first.status ?? null,
  })
}

// --- Profile upserted (signup) ---
if ('salary' in first && 'bufferWeeks' in first) return ack('profile', true, 'PROFILE_SAVED')

// --- Monthly expense list saved (Financial Overview) ---
if ('monthlyExpenses' in first) {
  const expenses = first.monthlyExpenses || []
  return ack('expenses', true, 'EXPENSES_SAVED', {
    count: expenses.length,
    totalCents: expenses.reduce((sum, e) => sum + Math.trunc(Number(e.amountCents || 0)), 0),
  })
}

// --- Salary edited (Financial Overview) ---
if ('salary' in first) return ack('salary', true, 'SALARY_SAVED', { salaryCents: first.salary ?? null })

// --- Afford question: nothing saved, return the verdict ---
if ('verdict' in first) {
  return ack('afford', false, 'AFFORD_' + String(first.verdict), {
    verdict: first.verdict,
    monthsNeeded: first.monthsNeeded ?? null,
    safeToSpendCents: first.safeToSpend ?? null,
    reachable: first.reachable ?? true,
  })
}

// --- Spending summary: nothing saved ---
if ('topMovers' in first || 'summaryData' in first) {
  return ack('summary', false, 'SUMMARY_READY', { summary: first.topMovers ?? null })
}

return ack('unknown', false, 'NOTHING_TO_SAVE')

