// Saves the user's whole list of monthly expenses from the Financial Overview.
// Their total becomes the "usual monthly spending" everywhere. Mode: Run Once for All Items.

const GROUPS = new Set(['essential', 'adjustable', 'optional'])
const MAX_ITEMS = 60
const MAX_NAME = 60

// Python-style rounding (half to even), so amounts match the earlier Python version exactly.
function pyRound(value) {
  const floor = Math.floor(value)
  const diff = value - floor
  if (diff > 0.5) return floor + 1
  if (diff < 0.5) return floor
  return floor % 2 === 0 ? floor : floor + 1
}

// Mauritius time: UTC+4, no daylight saving.
function mauritiusNow(offsetDays = 0) {
  const shifted = new Date(Date.now() + 4 * 3600e3 + offsetDays * 86400e3).toISOString()
  return { date: shifted.slice(0, 10), stamp: shifted.slice(0, 19) + '+04:00' }
}

const request = $input.first().json
const rawItems = request.monthlyExpenses
if (!Array.isArray(rawItems) || rawItems.length > MAX_ITEMS) throw new Error('INVALID_EXPENSES: send a list of up to 60 expenses')

const expenses = rawItems.map((raw) => {
  const entry = raw || {}
  const name = String(entry.name || '').trim().slice(0, MAX_NAME)
  const group = String(entry.group || '').trim().toLowerCase()
  const number = Number(entry.amountCents)
  if (entry.amountCents === undefined || entry.amountCents === null || entry.amountCents === '' || !Number.isFinite(number)) {
    throw new Error('INVALID_EXPENSES: every amount must be a number')
  }
  const amount = pyRound(number)
  if (!name || amount <= 0 || !GROUPS.has(group)) {
    throw new Error('INVALID_EXPENSES: each expense needs a name, an amount above 0 and a group')
  }
  return { name, amountCents: amount, group }
})

return [{ json: { userId: request.userId, monthlyExpenses: expenses, updatedAt: mauritiusNow().stamp } }]
